        require(IVisor(from).owner() == msg.sender);
        IVisor(from).delegatedTransferERC20(address(visr), address(this), visrDeposit);
    } else {
        visr.safeTransferFrom(from, address(this), visrDeposit);
    }

    vvisr.mint(to, shares);
}
```
